"""Stage 3 - Agent generator.

Produces a complete forgeai.agent/1 definition from requirements + documents:

* tools: the model proposes a decision for EVERY registry tool with the topic it
  serves; deterministic gates then veto anything whose precondition fails or
  whose need is not evidenced in the requirements, and add tools the
  groundability audit proved necessary. Every decision is logged with reasons.
* system prompt: sectioned; generated by the factory model, then the refusal
  and scope sections are deterministically completed so no must-refuse topic or
  groundability gap can be silently dropped by a small model.
* retrieval/chunking: corpus-aware starting point; the optimizer tunes it
  against measured recall.
"""

from __future__ import annotations

import datetime as _dt
import json
import re
from pathlib import Path

from forgeai import AGENT_SCHEMA_VERSION, __version__
from forgeai.factory.context import Run
from forgeai.factory.groundability import tool_preconditions
from forgeai.ingest.chunker import chunk_documents
from forgeai.llm.gateway import LLMError
from forgeai.llm.schema import BOOL, NESTR, STR, arr, obj
from forgeai.retrieval.index import KnowledgeIndex
from forgeai.runtime import definition as D
from forgeai.runtime.tools import REGISTRY, tables_from_docs
from forgeai.util import console as C
from forgeai.util.io import write_json
from forgeai.util.text import normalize

TOOL_SCHEMA = obj({"decisions": arr(obj({"tool": NESTR, "attach": BOOL, "serves_topic": STR, "reason": STR}), 1, 8)})
PROMPT_SCHEMA = obj({k: NESTR for k in D.SECTION_ORDER})

NEED_PATTERNS = {name: spec.need for name, spec in REGISTRY.items()}

STYLES = {
    "rules": "terse numbered rules, one instruction per line",
    "persona": "a short, warm expert persona followed by firm rules",
    "procedure": "a step-by-step answering procedure (read sources -> decide answerable -> answer -> cite)",
}


# ----------------------------------------------------------------- knowledge
def build_knowledge(run: Run, chunking: dict) -> tuple[list, KnowledgeIndex]:
    key = (int(chunking["max_chars"]), int(chunking["overlap"]))
    cache = run.__dict__.setdefault("_index_cache", {})
    if key not in cache:
        chunks = chunk_documents(run.docs, max_chars=key[0], overlap=key[1])
        cache[key] = (chunks, KnowledgeIndex.build(chunks, run.gw, stage="index"))
    return cache[key]


def initial_retrieval(run: Run) -> tuple[dict, dict]:
    text_docs = [d for d in run.docs if d.table is None]
    avg_sec = (sum(len(s.text) for d in text_docs for s in d.sections) /
               max(1, sum(len(d.sections) for d in text_docs))) if text_docs else 600
    max_chars = 700 if avg_sec < 500 else (900 if avg_sec < 1500 else 1100)
    codes = sum(1 for c in run.chunks[:400] if re.search(r"\b[A-Z]{2,}[-/]?\d{2,}", c.text))
    has_table = any(d.table is not None for d in run.docs)
    bm25_w = 0.55 if (has_table or codes > len(run.chunks[:400]) * 0.2) else 0.4
    return {"max_chars": max_chars, "overlap": 120}, \
        {"top_k": 6, "bm25_weight": bm25_w, "neighbours": 0, "query_rewrite": False}


# --------------------------------------------------------------------- tools
def _topic_match(name: str, topics: list[dict]) -> dict | None:
    n = normalize(name)
    for t in topics:
        tn = normalize(t["topic"])
        if n and (n == tn or n in tn or tn in n):
            return t
    return None


def select_tools(run: Run) -> list[dict]:
    req, g = run.requirements, run.groundability
    pre = tool_preconditions(run)
    registry_txt = "\n".join(f"- {n}: {s.description} Use for: {'; '.join(s.capabilities)}. Not for: "
                             f"{'; '.join(s.not_for)}." + ("" if pre[n] else " [UNAVAILABLE: precondition not met]")
                             for n, s in REGISTRY.items())
    corpus_facts = ", ".join(f"{d.path} ({'table' if d.table else d.kind})" for d in run.docs)
    try:
        decisions = run.gw.run_prompt("factory", "gen.tools", TOOL_SCHEMA, stage="generate.tools",
                                      requirements=_req_text(req), corpus_facts=corpus_facts,
                                      registry=registry_txt)["decisions"]
    except LLMError:
        decisions = []
    by_tool = {d["tool"]: d for d in decisions if d["tool"] in REGISTRY}
    gap_topics = {x["topic"] for x in g.get("gaps", [])}
    # evidence of need comes ONLY from required topics the corpus/tools can support
    need_text = " ".join(f"{t['topic']} {t.get('description', '')}" for t in req["must_answer"]
                         if t["topic"] not in gap_topics).lower()
    tool_backed = {x["tool"] for x in g.get("tool_backed", [])}
    table_evidence = any(any("#r" in r["chunk_id"] for r in t["retrieved"][:2]) for t in g.get("topics", [])
                         if t["verdict"] != "unsupported")
    out = []
    for name in REGISTRY:
        d = by_tool.get(name, {"tool": name, "attach": False, "serves_topic": "", "reason": "(no decision returned)"})
        need = bool(re.search(NEED_PATTERNS[name], need_text))
        gates = {"precondition": pre[name], "need_in_requirements": need,
                 "groundability_requires": name in tool_backed}
        attach = bool(d["attach"])
        why = d.get("reason", "")
        if attach and not pre[name]:
            attach, why = False, f"vetoed: precondition failed ({REGISTRY[name].requires or 'network'})"
        elif attach and _topic_match(d.get("serves_topic", ""), [{"topic": t} for t in gap_topics]) \
                and name not in tool_backed:
            attach, why = False, (f"vetoed: the topic it would serve ('{d.get('serves_topic')}') is a groundability "
                                  "gap the agent must decline")
        elif attach and not need and name not in tool_backed:
            attach, why = False, "vetoed: no supported requirement mentions a need this tool serves"
        if not attach and name in tool_backed and pre[name]:
            attach, why = True, "added: groundability audit found a required topic only this tool can serve"
        if not attach and name == "csv_lookup" and pre[name] and table_evidence and need:
            attach, why = True, "added: required topics are answered by table rows; exact lookup needed"
        serves = d.get("serves_topic", "")
        if attach and not _topic_match(serves, req["must_answer"]):
            m = next((t for t in req["must_answer"] if re.search(NEED_PATTERNS[name],
                                                                f"{t['topic']} {t.get('description', '')}".lower())), None)
            serves = m["topic"] if m else serves
        out.append({"tool": name, "attach": attach, "serves_topic": serves if attach else "",
                    "model_said": bool(d["attach"]), "model_reason": d.get("reason", ""), "final_reason": why,
                    "gates": gates})
    write_json(run.path("04_tool_decisions.json"), out)
    return out


# ------------------------------------------------------------- system prompt
def _req_text(req: dict) -> str:
    return json.dumps({k: req[k] for k in ("agent_name", "summary", "audience", "tone", "scope", "must_answer",
                                           "must_refuse", "out_of_scope_message") if k in req},
                      indent=1, ensure_ascii=False)


def _complete_sections(sec: dict, req: dict, g: dict, tools: list[dict]) -> dict:
    """Deterministic completion: guarantee scope, refusal and tool rules are explicit."""
    gaps = [x["topic"] for x in g.get("gaps", [])]
    refuse = [t["topic"] for t in req["must_refuse"]]
    supported = [t["topic"] for t in req["must_answer"] if t["topic"] not in gaps]
    low = sec.get("refusal", "").lower()
    missing = [t for t in refuse + gaps if normalize(t) not in normalize(low)]
    if missing:
        sec["refusal"] = sec.get("refusal", "").rstrip() + "\nAlways decline questions about: " + "; ".join(missing) + "."
    if req["out_of_scope_message"] not in sec.get("refusal", ""):
        sec["refusal"] += f"\nRefusal message: \"{req['out_of_scope_message']}\""
    if supported and not all(normalize(t) in normalize(sec.get("scope", "")) for t in supported[:3]):
        sec["scope"] = sec.get("scope", "").rstrip() + "\nYou answer questions on: " + "; ".join(supported) + "."
    attached = [t for t in tools if t["attach"]]
    if not attached:
        sec["tools"] = "No tools are available. Answer from the SOURCES only."
    else:
        rules = "\n".join(f"- {t['tool']}: use for {t['serves_topic'] or REGISTRY[t['tool']].capabilities[0]}."
                          for t in attached)
        if not all(t["tool"] in sec.get("tools", "") for t in attached):
            sec["tools"] = sec.get("tools", "").rstrip() + "\n" + rules
    return sec


def draft_prompt(run: Run, style: str, tools: list[dict]) -> dict:
    req, g = dict(run.requirements), run.groundability
    req["out_of_scope_message"] = refusal_message(req, g)
    gaps = "\n".join(f"- {x['topic']}" for x in g.get("gaps", [])) or "(none)"
    attached = ", ".join(t["tool"] for t in tools if t["attach"]) or "none"
    try:
        sec = run.gw.run_prompt("factory", "gen.system_prompt", PROMPT_SCHEMA, stage="generate.prompt",
                                style=STYLES[style], requirements=_req_text(req), gaps=gaps, tools=attached,
                                refusal_message=req["out_of_scope_message"])
    except LLMError:
        sec = fallback_sections(req)
    return _complete_sections(sec, req, g, tools)


def fallback_sections(req: dict) -> dict:
    topics = "; ".join(t["topic"] for t in req["must_answer"])
    return {
        "role": f"You are {req['agent_name']}. {req['summary']}",
        "audience_tone": f"You help {req['audience']}. Tone: {req['tone']}.",
        "scope": f"{req['scope']}\nYou answer questions on: {topics}.",
        "grounding": "Use ONLY the SOURCES given with each question. Quote numbers, dates and names exactly. "
                     "Cite every passage you use. If the sources do not contain the answer, say so and refuse.",
        "refusal": f"Decline anything outside your scope. Refusal message: \"{req['out_of_scope_message']}\"",
        "tools": "No tools are available.",
        "format": "Give the direct answer first in one or two sentences, then key details as short bullets.",
    }


# ---------------------------------------------------------------- definition
def refusal_message(req: dict, g: dict) -> str:
    """The requester's refusal message - unless it advertises a topic the
    documents cannot support, in which case a truthful one is composed."""
    msg = req["out_of_scope_message"]
    gaps = [x["topic"] for x in g.get("gaps", [])]
    from forgeai.util.text import content_tokens
    mt = set(content_tokens(msg))
    advertises = [t for t in gaps if (lambda tt: tt and len(tt & mt) / len(tt) >= 0.5)(set(content_tokens(t)))]
    if not advertises:
        return msg
    supported = [(t["topic"][0].lower() + t["topic"][1:]) if t["topic"][1:2].islower() else t["topic"]
                 for t in req["must_answer"] if t["topic"] not in gaps]
    return ("Sorry, I can't help with that. I can answer questions about "
            + (", ".join(supported[:-1]) + " and " + supported[-1] if len(supported) > 1 else "".join(supported))
            + ". For anything else, please contact the responsible team.")


def assemble(run: Run, sections: dict, tools: list[dict], chunking: dict, retrieval: dict, style: str) -> dict:
    req, g = run.requirements, run.groundability
    return {
        "schema_version": AGENT_SCHEMA_VERSION,
        "name": req["agent_name"],
        "description": req["summary"],
        "version": 0,
        "model": {"name": run.settings.agent_model, "temperature": 0.0, "max_tokens": 700,
                  "num_ctx": run.settings.num_ctx},
        "system_prompt": {"style": style, "sections": [{"id": k, "text": sections[k].strip()} for k in D.SECTION_ORDER]},
        "knowledge": {
            "index_dir": "knowledge",
            "embed_model": run.settings.embed_model,
            "documents": [{"doc_id": d.doc_id, "path": d.path, "kind": d.kind, "sha256": d.sha256} for d in run.docs],
            "chunking": chunking,
            "retrieval": retrieval,
        },
        "tools": [{"name": t["tool"], "reason": t["final_reason"] or t["model_reason"], "serves_topic": t["serves_topic"]}
                  for t in tools if t["attach"]],
        "output_contract": D.OUTPUT_CONTRACT,
        "guards": {"min_relevance": 0.0, "max_tool_rounds": 2, "require_citations": True},
        "refusal_policy": {
            "message": refusal_message(req, g),
            "must_refuse_topics": [t["topic"] for t in req["must_refuse"]],
            "unsupported_topics": [x["topic"] for x in g.get("gaps", [])],
        },
        "provenance": {"factory": f"forgeai {__version__}",
                       "created": _dt.datetime.now(_dt.timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ"),
                       "brief": run.brief, "changes": []},
    }


def save_agent(run: Run, defn: dict, folder: Path | None = None) -> Path:
    """Write agent.json plus its self-contained knowledge index."""
    folder = folder or run.path("agent")
    folder.mkdir(parents=True, exist_ok=True)
    chunks, index = build_knowledge(run, defn["knowledge"]["chunking"])
    index.save(folder / defn["knowledge"]["index_dir"])
    write_json(folder / defn["knowledge"]["index_dir"] / "tables.json", tables_from_docs(run.docs))
    errs = D.check(defn)
    if errs:
        raise ValueError("generated definition failed validation: " + "; ".join(errs))
    D.save(defn, folder / "agent.json")
    return folder / "agent.json"


def generate(run: Run, styles: list[str]) -> tuple[list[dict], list[dict]]:
    tools = select_tools(run)
    attached = [t["tool"] for t in tools if t["attach"]]
    C.ok(f"tools attached: {', '.join(attached) or 'none'}  "
         f"(considered {len(tools)}; vetoed {sum(1 for t in tools if t['model_said'] and not t['attach'])})")
    chunking, retrieval = initial_retrieval(run)
    cands = run.pmap(lambda s: (s, draft_prompt(run, s, tools)), styles,
                     "drafting system prompt" + ("s" if len(styles) > 1 else ""))
    defs = [assemble(run, sec, tools, chunking, retrieval, s) for s, sec in cands]
    return defs, tools
